<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Invoice Number Generator','description'=>'Generate unique invoice numbers for quick testing and small workflows.','url'=>'https://smarttoolz.in/tools/invoice-number-generator/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>Invoice Number Generator</h1><p>Generate unique invoice numbers instantly.</p></section><section class="tool-workspace"><div class="tool-panel"><input id="p" value="INV-"><button id="go" class="tool-btn">Generate</button><textarea id="o" rows="10" readonly></textarea></div></section></main><script>go.onclick=()=>o.value=Array.from({length:10},()=>p.value+Date.now().toString(36).toUpperCase()+'-'+Math.random().toString(36).slice(2,6).toUpperCase()).join('\n');go.click()</script><?php smarttoolz_tool_page_end(); ?>